const { createDebugHelper } = require('./ko-debug.js');

// Define a sample ViewModel with the required properties
const sampleViewModel = {
  items: [],
  selectedItem: null,
  filterText: '',
  isLoading: false,
  totalCount: 0
};

// Create the debug helper
const debugHelper = createDebugHelper(sampleViewModel);

let allPassed = true;

function runTest(description, actual, expected) {
  const passed = JSON.stringify(actual) === JSON.stringify(expected);
  if (passed) {
    console.log('PASS: ' + description);
  } else {
    console.log('FAIL: ' + description);
    console.log('  Expected: ' + JSON.stringify(expected));
    console.log('  Got:      ' + JSON.stringify(actual));
    allPassed = false;
  }
  return passed;
}

// Test 1: Diagnose missing property "item" - should suggest "items"
const result1 = debugHelper.diagnoseMissingProperty('item');
runTest(
  'Test 1: "item" should suggest "items"',
  {
    error: result1.error,
    missingProperty: result1.missingProperty,
    availableProperties: result1.availableProperties,
    suggestion: result1.suggestion
  },
  {
    error: true,
    missingProperty: 'item',
